ort type EffectAllowed = DomDataTransfer[ 'effectAllowed' ];\n\n/**\n * The actual drop effect.\n */\nexport type DropEffect = DomDataTransfer[ 'dropEffect' ];\n\nfunction getFiles( nativeDataTransfer: DomDataTransfer ): Array<File> {\n\t// DataTransfer.files and items are array-like and might not have an iterable interface.\n\tconst files = Array.from( nativeDataTransfer.files || [] );\n\tconst items = Array.from( nativeDataTransfer.items || [] );\n\n\tif ( files.length ) {\n\t\treturn files;\n\t}\n\n\t// Chrome has empty DataTransfer.files, but allows getting files through the items interface.\n\treturn items\n\t\t.filter( item => item.kind === 'file' )\n\t\t.map( item => item.getAsFile()! );\n}\n","/**\n * @license Copyright (c) 2003-2025, CKSource Holding sp. z o.o. All rights reserved.\n * For licensing, see LICENSE.md or https://ckeditor.com/legal/ckeditor-licensing-options\n */\n\n/**\n * @module engine/view/observer/inputobserver\n */\n\nimport DomEventObserver from './domeventobserver.js';\nimport type DomEventData from './domeventdata.js';\nimport type ViewRange from '../range.js';\nimport DataTransfer from '../datatransfer.js';\nimport { env } from '@ckeditor/ckeditor5-utils';\n\n// @if CK_DEBUG_TYPING // const { _debouncedLine } = require( '../../dev-utils/utils.js' );\n\n/**\n * Observer for events connected with data input.\n *\n * **Note**: This observer is attached by {@link module:engine/view/view~View} and available by default in all\n * editor instances.\n */\nexport default class InputObserver extends DomEventObserver<'beforeinput'> {\n\t/**\n\t * @inheritDoc\n\t */\n\tpublic readonly domEventType = 'beforeinput' as const;\n\n\t/**\n\t * @inheritDoc\n\t */\n\tpublic onDomEvent( domEvent: InputEvent ): void {\n\t\t// @if CK_DEBUG_TYPING // if ( ( window as any ).logCKETyping ) {\n\t\t// @if CK_DEBUG_TYPING // \t_debouncedLine();\n\t\t// @if CK_DEBUG_TYPING // \tconsole.group( `%c[InputObserver]%c ${ domEvent.type }: ${ domEvent.inputType }`,\n\t\t